create or replace function public.novacart_mark_slack_sent(p_ticket uuid,p_timestamp text) returns jsonb language plpgsql security invoker set search_path='' as $$ begin update public.novacart_outbox set status='sent',attempts=least(attempts+1,3),payload=payload||jsonb_build_object('slack_timestamp',left(p_timestamp,100)) where ticket_id=p_ticket and channel='slack' and status='held'; if not found then return jsonb_build_object('marked',false); end if; insert into public.novacart_workflow_logs(ticket_id,event,detail) values(p_ticket,'slack_sent',jsonb_build_object('slack_timestamp',left(p_timestamp,100))); return jsonb_build_object('marked',true); end $$; revoke all on function public.novacart_mark_slack_sent(uuid,text) from public,anon,authenticated; grant execute on function public.novacart_mark_slack_sent(uuid,text) to service_role;